"use client";import{FormEvent,useCallback,useEffect,useState}from"react";type Row=Record<string,unknown>;type Data={trades:Row[];costs:Row[];expenses:Row[];items:Row[];report:Row[];summary:Row;isolationProof:Row};const c="w-full rounded-lg border px-3 py-2";const money=(v:unknown)=>`${Number(v??0).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})} ر.س`;
export default function ExternalClient(){const[data,setData]=useState<Data|null>(null),[message,setMessage]=useState("");const load=useCallback(async()=>{const r=await fetch("/api/external",{cache:"no-store"}),x=await r.json();if(!r.ok)throw new Error(x.error);setData(x)},[]);useEffect(()=>{let stop=false;fetch("/api/external",{cache:"no-store"}).then(r=>r.json()).then(x=>{if(!stop)setData(x)}).catch(e=>setMessage(e.message));return()=>{stop=true}},[]);async function send(url:string,body:Row){const r=await fetch(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}),x=await r.json();if(!r.ok){setMessage(x.error);return null}setMessage("تم الحفظ في الدفتر الخارجي المستقل");await load();return x}if(!data)return <div className="p-8">{message||"جارٍ التحميل…"}</div>;return <div className="mx-auto max-w-7xl p-6">{message&&<div className="mb-4 rounded-lg bg-amber-50 p-3">{message}</div>}<div className="mb-6 grid gap-4 md:grid-cols-3">{[["المبيعات الخارجية",money(data.summary.sales)],["التكلفة الخارجية",money(data.summary.cost)],["صافي الربح",money(data.summary.profit)]].map(([l,v])=><div key={l} className="rounded-2xl border bg-white p-5"><p className="text-sm text-slate-500">{l}</p><b className="text-xl">{v}</b></div>)}</div><div className="grid gap-5 lg:grid-cols-3"><TradeForm data={data} send={send}/><CostForm data={data} send={send}/><ExpenseForm send={send}/></div><section className="mt-6 rounded-2xl border bg-white p-5"><h2 className="mb-4 font-bold">ربحية المواد الخارجية</h2><Table h={["المادة","شراء كمية","قيمة الشراء","بيع كمية","المبيعات","النقل","تكاليف أخرى","إجمالي التكلفة","الربح","الهامش","ربح/طن"]} r={data.report.map(x=>[x.itemName,x.purchasedQty,money(x.purchasedValue),x.soldQty,money(x.salesValue),money(x.transportCost),money(x.otherCost),money(x.totalCost),money(x.netProfit),`${Number(x.margin).toFixed(2)}%`,money(x.profitPerTon)])}/></section><p className="mt-4 rounded-lg bg-emerald-50 p-3 text-sm text-emerald-800">العزل مؤكد: لم تُنشئ هذه الوحدة حركات مخزون أو قيودًا أو فواتير داخلية. العدادات الداخلية للقراءة والتحقق فقط.</p></div>}
function Items({data}:{data:Data}){return <select name="itemId" required className={c}><option value="">المادة</option>{data.items.map(x=><option key={String(x.id)} value={String(x.id)}>{String(x.nameAr)}</option>)}</select>}function TradeForm({data,send}:{data:Data;send:(u:string,b:Row)=>Promise<unknown>}){async function go(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=e.currentTarget,r=await send("/api/external/trades",Object.fromEntries(new FormData(f)));if(r)f.reset()}return <form onSubmit={go} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">شراء/بيع خارجي</h2><input name="tradeDate" type="date" defaultValue={new Date().toISOString().slice(0,10)} className={c}/><select name="tradeType" className={c}><option value="PURCHASE">شراء خارجي</option><option value="SALE">بيع خارجي</option></select><Items data={data}/><input name="entityName" required placeholder="الجهة الخارجية" className={c}/><input name="quantity" type="number" min="0.001" step="0.001" required placeholder="الكمية" className={c}/><input name="unitPrice" type="number" min="0.01" step="0.01" required placeholder="سعر الوحدة" className={c}/><button className="w-full rounded-lg bg-blue-600 py-2 text-white">حفظ</button></form>}
function CostForm({data,send}:{data:Data;send:(u:string,b:Row)=>Promise<unknown>}){async function go(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=e.currentTarget,r=await send("/api/external/costs",Object.fromEntries(new FormData(f)));if(r)f.reset()}return <form onSubmit={go} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">تكلفة مرتبطة</h2><input name="costDate" type="date" defaultValue={new Date().toISOString().slice(0,10)} className={c}/><Items data={data}/><select name="costType" className={c}><option value="TRANSPORT">نقل</option><option value="OTHER">أخرى</option></select><select name="externalTradeId" className={c}><option value="">عملية مرتبطة (اختياري)</option>{data.trades.map(x=><option key={String(x.id)} value={String(x.id)}>{String(x.tradeNumber)}</option>)}</select><input name="amount" type="number" min="0.01" step="0.01" required placeholder="التكلفة" className={c}/><input name="description" placeholder="البيان" className={c}/><button className="w-full rounded-lg bg-amber-600 py-2 text-white">حفظ</button></form>}
function ExpenseForm({send}:{send:(u:string,b:Row)=>Promise<unknown>}){async function go(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=e.currentTarget,r=await send("/api/external/expenses",Object.fromEntries(new FormData(f)));if(r)f.reset()}return <form onSubmit={go} className="space-y-3 rounded-2xl border bg-white p-5"><h2 className="font-bold">مصروف خارجي مستقل</h2><input name="expenseDate" type="date" defaultValue={new Date().toISOString().slice(0,10)} className={c}/><input name="entityName" placeholder="الجهة" className={c}/><input name="category" required placeholder="التصنيف" className={c}/><input name="description" required placeholder="الوصف" className={c}/><input name="amount" type="number" min="0.01" step="0.01" required placeholder="المبلغ" className={c}/><input name="paymentMethod" placeholder="طريقة الدفع" className={c}/><button className="w-full rounded-lg bg-rose-600 py-2 text-white">حفظ</button></form>}
function Table({h,r}:{h:string[];r:unknown[][]}){return <div className="overflow-x-auto"><table className="w-full text-sm"><thead className="bg-slate-100"><tr>{h.map(x=><th key={x} className="p-3 text-right">{x}</th>)}</tr></thead><tbody>{r.map((x,i)=><tr key={i} className="border-b">{x.map((v,j)=><td key={j} className="whitespace-nowrap p-3">{String(v??"—")}</td>)}</tr>)}</tbody></table>{!r.length&&<p className="p-8 text-center">لا توجد بيانات.</p>}</div>}
